-- ============================================================
-- IBA Written Preparation — Question Bank
-- FULL BATCH (500 of 500) — difficulty stepped down one level
--   new very_hard  ≈ old hard      (concrete real-world debate, not abstract theory)
--   new hard       ≈ old medium    (familiar debate, moderate depth)
--   new medium     ≈ old easy      (simple, direct topical question)
--   new easy       <  old easy     (very concrete, everyday, minimal background needed)
-- question_category enum: basic_paragraph, personal_reflection,
--   creative_writing, quote_analysis, 
-- difficulty_level enum: easy, medium, hard, very_hard
-- ============================================================

-- ===================== BASIC_PARAGRAPH (8) =====================

-- 1. Automation & UBI | Very Hard | 15 marks
VALUES (
  'basic_paragraph', 15, 'very_hard', NULL,
  'As automation threatens millions of jobs, should governments guarantee a universal basic income to offset the disruption? Develop a balanced argument before defending your own position.',
  'You''ll get one and a half pages in the real IBA exam',
  2
);

-- 2. Digital privacy vs surveillance | Very Hard | 12 marks
VALUES (
  'basic_paragraph', 12, 'very_hard', NULL,
  'Should governments be allowed to expand digital surveillance in the name of security, even at the cost of citizens'' privacy? Evaluate both sides before defending your position.',
  'You''ll get a bit more than one page in the real IBA exam',
  2
);

-- 3. Corporate pollution responsibility | Hard | 13 marks
VALUES (
  'basic_paragraph', 13, 'hard', NULL,
  'Should big companies be required to spend part of their profits fixing the pollution they cause, even if it reduces returns for shareholders?',
  'You''ll get a bit more than one page in the real IBA exam',
  2
);

-- 4. Meritocracy myth | Hard | 12 marks
VALUES (
  'basic_paragraph', 12, 'hard', NULL,
  'Is meritocracy a realistic ideal, or does unequal access to wealth and education make it a myth that legitimizes inequality? Present a balanced argument before defending your conclusion.',
  'You''ll get a bit more than one page in the real IBA exam',
  2
);

-- 5. Bangladesh brain drain | Hard | 10 marks
VALUES (
  'basic_paragraph', 10, 'hard', NULL,
  'As thousands of Bangladesh''s brightest graduates leave the country each year and rarely return, how should the nation respond to this brain drain? Defend a specific course of action.',
  'You''ll get a whole page in the real IBA exam',
  1
);

-- 6. Space exploration budget | Medium | 10 marks
VALUES (
  'basic_paragraph', 10, 'medium', NULL,
  'Should nations continue funding ambitious space exploration missions while poverty and hunger persist on Earth? Develop a balanced argument before defending your position.',
  'You''ll get a whole page in the real IBA exam',
  1
);

-- 7. University admissions criteria | Medium | 10 marks
VALUES (
  'basic_paragraph', 10, 'medium', NULL,
  'Should university admissions rely only on entrance exam scores, or should extracurricular achievements count too? Defend your own view.',
  'You''ll get a whole page in the real IBA exam',
  1
);

-- 8. Mobile phones in schools | Easy | 10 marks
VALUES (
  'basic_paragraph', 10, 'easy', NULL,
  'Should schools ban mobile phones during class hours? Give reasons for your position.',
  'You''ll get a whole page in the real IBA exam',
  1
);

-- ===================== QUOTE_ANALYSIS (4) =====================

-- 9. Nietzsche | Hard | 6 marks
VALUES (
  'quote_analysis', 6, 'hard', NULL,
  'Nietzsche wrote, "He who has a why to live can bear almost any how." Analyze what this suggests about the role of purpose in overcoming hardship.',
  'You''ll get a bit more than half a page in the real IBA exam',
  1
);

-- 10. Marcus Aurelius | Medium | 5 marks
VALUES (
  'quote_analysis', 5, 'medium', NULL,
  'Marcus Aurelius wrote, "What stands in the way becomes the way." Explain what this quote means, and describe a situation where this idea could apply.',
  'You''ll get about half a page in the real IBA exam',
  1
);

-- 11. Rumi | Medium | 6 marks
VALUES (
  'quote_analysis', 6, 'medium', NULL,
  'Rumi wrote, "The wound is the place where the light enters you." Explain what this metaphor means, and share your own view on whether pain helps people grow.',
  'You''ll get a bit more than half a page in the real IBA exam',
  1
);

-- 12. Maya Angelou | Easy | 5 marks
VALUES (
  'quote_analysis', 5, 'easy', NULL,
  'Maya Angelou said, "People will forget what you said, but never how you made them feel." Explain what this quote means to you, using an example from your own life.',
  'You''ll get about half a page in the real IBA exam',
  1
);

-- ===================== CREATIVE_WRITING (4) — story prompts =====================

-- 13. Alternate history: no printing press | Very Hard | 15 marks
VALUES (
  'creative_writing', 15, 'very_hard', NULL,
  'Imagine the printing press was never invented, and handwritten manuscripts remain the only way to record knowledge today. Write a story set in this world.',
  'You''ll get one and a half pages in the real IBA exam',
  2
);

-- 14. The AI judge | Hard | 12 marks
VALUES (
  'creative_writing', 12, 'hard', NULL,
  'In 2045, an AI judge decides court cases and is praised for being fair. Write a story about a lawyer who starts to notice something isn''t right about its decisions.',
  'You''ll get a bit more than one page in the real IBA exam',
  2
);

-- 15. Time travel: conversation with younger self | Medium | 8 marks
VALUES (
  'creative_writing', 8, 'medium', NULL,
  'You get one chance to speak with yourself at age sixteen, without revealing any facts about the future. Write a story of this conversation.',
  'You''ll get a bit more than half a page in the real IBA exam',
  1
);

-- 16. Superpower for a day | Easy | 6 marks
VALUES (
  'creative_writing', 6, 'easy', NULL,
  'Write a story about waking up one morning with an unexpected superpower that lasts for exactly one day.',
  'You''ll get a bit more than half a page in the real IBA exam',
  1
);

