INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should influencers be required to clearly label sponsored posts, even when it might reduce their earnings?', 'You''ll get a whole page in the real IBA exam', 1); -- Social Media
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should stores be banned from using discount tags like "50% off" if the original price was never actually charged?', 'You''ll get a whole page in the real IBA exam', 1); -- Consumerism
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should cities build more bicycle lanes even if it means removing some car parking spaces?', 'You''ll get a whole page in the real IBA exam', 1); -- Urbanization
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should news channels be required to clearly separate opinion segments from factual reporting?', 'You''ll get a whole page in the real IBA exam', 1); -- Media
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Does having more money genuinely make people happier, or does happiness mostly come from elsewhere?', 'You''ll get a whole page in the real IBA exam', 1); -- Happiness
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should statues of historically controversial figures be removed from public spaces, or kept with added context?', 'You''ll get a whole page in the real IBA exam', 1); -- History
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should schools require students to learn about festivals from religions other than their own?', 'You''ll get a whole page in the real IBA exam', 1); -- Culture
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should people be free to say anything they want online, even if it hurts someone''s feelings?', 'You''ll get a whole page in the real IBA exam', 1); -- Freedom
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Is winning a competition always a fair way to measure who worked hardest?', 'You''ll get a whole page in the real IBA exam', 1); -- Success & Failure
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Is it better to make quick decisions and adjust later, or take time to plan carefully first?', 'You''ll get a whole page in the real IBA exam', 1); -- Decision Making
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should team captains be chosen by a vote from teammates, or picked by the coach?', 'You''ll get a whole page in the real IBA exam', 1); -- Power
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Can staying hopeful actually help someone solve a difficult problem, or is it just a feeling?', 'You''ll get a whole page in the real IBA exam', 1); -- Hope
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'As AI writing tools become common in schools, should students be allowed to use them for homework?', 'You''ll get a whole page in the real IBA exam', 1); -- AI
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should individual people be blamed for climate change, or is it mainly the responsibility of large companies?', 'You''ll get a whole page in the real IBA exam', 1); -- Climate Change
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Does raising the minimum wage genuinely help workers overall, or does it lead to fewer available jobs?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Economics
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Why do people often continue bad habits even when they know those habits are harmful?', 'You''ll get a whole page in the real IBA exam', 1); -- Behavioral Psychology
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should letter and number grades be replaced with detailed written feedback instead?', 'You''ll get a whole page in the real IBA exam', 1); -- Education
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Is it better for a leader to be liked by their team, or respected even if not always liked?', 'You''ll get a whole page in the real IBA exam', 1); -- Leadership
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should small local shops be protected from competition with large chain stores?', 'You''ll get a whole page in the real IBA exam', 1); -- Business
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Is starting a business mostly about having a good idea, or about persistence when things go wrong?', 'You''ll get a whole page in the real IBA exam', 1); -- Entrepreneurship
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should young people be allowed to vote starting at age sixteen instead of eighteen?', 'You''ll get a whole page in the real IBA exam', 1); -- Politics
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Does holding frequent elections make a government more accountable, or does it distract from long-term planning?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Democracy
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Do strict copyright laws help or hurt innovation in creative industries?', 'You''ll get a whole page in the real IBA exam', 1); -- Innovation
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should children under a certain age be restricted from owning smartphones?', 'You''ll get a whole page in the real IBA exam', 1); -- Technology
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Does working from home make employees more productive, or does working from an office matter for teamwork?', 'You''ll get a whole page in the real IBA exam', 1); -- Future of Work
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Does globalization mostly benefit large economies, or does it help developing countries close the gap?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Globalization
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Are people naturally more cooperative or more competitive by instinct?', 'You''ll get a whole page in the real IBA exam', 1); -- Human Nature
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Can a person live a meaningful life without ever achieving anything widely considered a "success"?', 'You''ll get a whole page in the real IBA exam', 1); -- Philosophy
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should students be required to read classic literature, or should modern books get equal focus?', 'You''ll get a whole page in the real IBA exam', 1); -- Literature
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should scientific research that could be misused, such as certain genetic experiments, still be published openly?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Science
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should governments subsidize public transportation to reduce traffic and pollution in cities?', 'You''ll get a whole page in the real IBA exam', 1); -- Public Policy
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should first-time offenders of minor crimes receive community service instead of jail time?', 'You''ll get a whole page in the real IBA exam', 1); -- Law
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Does growing up across more than one culture make it harder or easier to build a clear sense of identity?', 'You''ll get a whole page in the real IBA exam', 1); -- Identity
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Do loyalty programs and reward points genuinely benefit customers, or mainly encourage overspending?', 'You''ll get a whole page in the real IBA exam', 1); -- Consumerism
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should schools include mental health education as a required part of the curriculum?', 'You''ll get a whole page in the real IBA exam', 1); -- Mental Health
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should plastic packaging be banned for products that have reasonable alternatives available?', 'You''ll get a whole page in the real IBA exam', 1); -- Environmental Sustainability
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Does strict punishment alone reduce corruption, or does it require changing the systems that allow it?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Corruption
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should the age at which someone can be tried as an adult in court be changed?', 'You''ll get a whole page in the real IBA exam', 1); -- Justice
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'When a team fails at a task, should responsibility fall mainly on the leader or on the whole team equally?', 'You''ll get a whole page in the real IBA exam', 1); -- Responsibility
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should wealthier nations be required to accept more refugees than poorer nations?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- International Relations
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Can creativity be taught, or is it mostly a natural talent some people are born with?', 'You''ll get a whole page in the real IBA exam', 1); -- Creativity
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should the religious holidays of all major faiths be recognized as public holidays in diverse countries?', 'You''ll get a whole page in the real IBA exam', 1); -- Religion & Society
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should smaller nations have equal voting power to larger nations in organizations like the United Nations?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Geopolitics
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should Bangladesh prioritize building more industries or protecting more farmland as its population grows?', 'You''ll get a whole page in the real IBA exam', 1); -- Bangladesh Development
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Is it ever acceptable to lie in order to protect someone else''s feelings?', 'You''ll get a whole page in the real IBA exam', 1); -- Morality
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Do people need a clear life purpose to feel genuinely fulfilled, or can daily enjoyment be enough?', 'You''ll get a whole page in the real IBA exam', 1); -- Purpose
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should universities be allowed to cancel invited speakers whose views many students find offensive?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Free Speech
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'If a statistic is technically true but used to create a misleading impression, is presenting it dishonest?', 'You''ll get a whole page in the real IBA exam', 1); -- Logical Reasoning
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'If you found a wallet full of cash with no ID inside, should returning it depend on how much money was there?', 'You''ll get a whole page in the real IBA exam', 1); -- Ethical Dilemma
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should companies be allowed to test their products on animals if doing so could prevent harm to humans?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Ethics
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'As private companies increasingly lead space missions, should resources like asteroid minerals belong to whoever reaches them first, or be shared internationally?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Space Exploration
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'As cities grow taller and denser, should governments limit building heights to preserve neighborhood character, even if it worsens housing shortages?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Urbanization
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Does holding power for a long time inevitably corrupt even well-intentioned leaders, or can strong institutions prevent this?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Power
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Is resilience something built through repeated hardship, or does constant hardship eventually break a person instead of strengthening them?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Resilience
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should governments tax unhealthy foods like sugary drinks to reduce health costs, even though this disproportionately affects lower-income families?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Public Policy
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should leadership of a family-run business pass to relatives, or go to the most qualified person regardless of family ties?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Business
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Does patenting new technology encourage innovation by protecting inventors, or slow it down by blocking others from building on new ideas?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Innovation
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'very_hard', NULL, 'Should companies be allowed to sell anonymized user data to advertisers if users technically agreed to lengthy terms and conditions they never read?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Digital Privacy
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'As algorithm-driven news feeds show people content that confirms their existing beliefs, should platforms be legally required to also show opposing viewpoints?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Media
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'Should juries be replaced by panels of expert judges in complex cases, even if this reduces the role of ordinary citizens in justice?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Law
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should people be honest about using AI tools to help write personal messages to friends?', 'You''ll get a whole page in the real IBA exam', 1); -- AI
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should families be encouraged to eat less meat to help reduce their carbon footprint?', 'You''ll get a whole page in the real IBA exam', 1); -- Climate Change
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should schools teach students how to manage a personal budget?', 'You''ll get a whole page in the real IBA exam', 1); -- Economics
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Why do people often procrastinate on tasks they know are important?', 'You''ll get a whole page in the real IBA exam', 1); -- Behavioral Psychology
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should schools reduce the number of standardized tests students take each year?', 'You''ll get a whole page in the real IBA exam', 1); -- Education
