INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Would a four-day work week make employees more productive, or just more tired by Friday?', 'You''ll get a whole page in the real IBA exam', 1); -- Future of Work
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should any books ever be removed from school libraries?', 'You''ll get a whole page in the real IBA exam', 1); -- Literature
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should people think twice before buying clothes they will only wear once or twice?', 'You''ll get a whole page in the real IBA exam', 1); -- Consumerism
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Does luck play a bigger role in success than most successful people admit?', 'You''ll get a whole page in the real IBA exam', 1); -- Success & Failure
