INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'If a product claims to be "90% natural," does that make it a genuinely healthy choice?', 'You''ll get a whole page in the real IBA exam', 1); -- Logical Reasoning
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should employees who report their company''s wrongdoing be legally protected, even if it damages the company?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Ethics
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should leaders make quick decisions during a crisis, even without complete information?', 'You''ll get a whole page in the real IBA exam', 1); -- Leadership
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should companies be allowed to move factories abroad if it means cheaper prices for customers?', 'You''ll get a whole page in the real IBA exam', 1); -- Business
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should failing at a business be seen as a normal part of eventually succeeding?', 'You''ll get a whole page in the real IBA exam', 1); -- Entrepreneurship
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should elected leaders be limited to a fixed number of terms in office?', 'You''ll get a whole page in the real IBA exam', 1); -- Politics
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should important national decisions be made through public referendums instead of elected representatives?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Democracy
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Can an algorithm used to make hiring decisions ever be truly free of bias?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Technology
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Does global trade make local cultures more similar over time, and is that a problem?', 'You''ll get a whole page in the real IBA exam', 1); -- Globalization
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Do people usually help others out of genuine kindness, or because it benefits them too?', 'You''ll get a whole page in the real IBA exam', 1); -- Human Nature
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should modern nations formally apologize for actions committed generations ago under different governments?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- History
