INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should governments fund ocean exploration as seriously as they fund space exploration?', 'You''ll get a whole page in the real IBA exam', 1); -- Science
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'As renovated neighborhoods become more expensive, should original residents be guaranteed housing there?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Urbanization
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should the right to self-defense allow force even when a person could safely retreat instead?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Law
