INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Is it possible to feel equally connected to a national identity and a global one?', 'You''ll get a whole page in the real IBA exam', 1); -- Identity
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should religious beliefs influence public policy in a country with citizens of many faiths?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Religion & Society
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should fast fashion brands be held responsible for the environmental damage their industry causes?', 'You''ll get a whole page in the real IBA exam', 1); -- Consumerism
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Does spending time on social media affect teenagers'' mental health more than it affects adults?', 'You''ll get a whole page in the real IBA exam', 1); -- Mental Health
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Is offering a small bribe to speed up a process a minor issue, or does it enable larger corruption?', 'You''ll get a whole page in the real IBA exam', 1); -- Corruption
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should the justice system focus more on punishing offenders or on repairing the harm done to victims?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Justice
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should people be willing to give up some personal freedom in exchange for greater safety?', 'You''ll get a whole page in the real IBA exam', 1); -- Freedom
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Does foreign aid actually help developing countries, or does it create long-term dependency?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- International Relations
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'If an AI generates a painting from a text prompt, should the person who wrote the prompt be called the artist?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Creativity
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Does deciding as a group lead to better outcomes, or does it encourage people to just follow the loudest opinion?', 'You''ll get a whole page in the real IBA exam', 1); -- Decision Making
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should people choose careers based on personal passion, or based on what best supports a family?', 'You''ll get a whole page in the real IBA exam', 1); -- Purpose
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should crewed missions to Mars proceed even though robotic missions can gather similar scientific data at a fraction of the risk and cost?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Space Exploration
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should healthcare be fully funded by the government for all citizens, even if it means significantly higher taxes for everyone?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Public Policy
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Do economic sanctions actually change the behavior of governments they target, or do they mainly harm ordinary citizens?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Geopolitics
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'As Bangladesh''s economy relies heavily on remittances from workers abroad, is this a sustainable path to long-term development?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Bangladesh Development
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'When a company funds charitable causes while also causing environmental harm, does the charity work genuinely offset that harm?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Responsibility
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should quality journalism be locked behind paywalls, even if it means only wealthier readers can access reliable information?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Media
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Is a country''s soft power, built through culture and diplomacy, ultimately more effective than its military strength?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Power
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'After a natural disaster, does a community''s recovery depend more on outside aid or on its own internal resilience?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Resilience
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'If different cultures hold genuinely conflicting moral values, is it possible for any moral standard to be truly universal?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Morality
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should autonomous weapons that can select and engage targets without human approval be banned globally, even if some nations refuse to sign such a ban?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- AI
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should nuclear energy be expanded as a solution to climate change, despite the risks and challenges of radioactive waste?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Environmental Sustainability
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should governments regulate how fast artificial intelligence is developed, even if it means falling behind other nations technologically?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Innovation
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Does a society''s overall wealth improve the happiness of its citizens beyond a certain basic standard of living?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Happiness
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should university degrees remain the main requirement for well-paying jobs, or should skills-based hiring replace them entirely?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Education
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should multinational companies be held to the labor laws of their home country when operating factories abroad?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Business
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should the same online platforms be allowed to act as both marketplace and seller, competing directly with businesses that depend on them?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Technology
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'If saving five strangers meant actively causing harm to one uninvolved person, would that choice ever be justified?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Ethical Dilemma
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'Should facial recognition technology be allowed in public spaces like train stations to prevent crime, despite the loss of anonymity for everyone who passes through?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Digital Privacy
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'Should social media platforms be held legally responsible for misinformation that spreads on them, similar to how publishers are responsible for content?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Free Speech
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'As younger generations increasingly share a global online culture, is the loss of some local traditions an acceptable cost of that connection?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Culture
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should companies be required to offer free returns on items bought online?', 'You''ll get a whole page in the real IBA exam', 1); -- Business
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Does trying many small experiments lead to better new ideas than carefully planning one big idea?', 'You''ll get a whole page in the real IBA exam', 1); -- Innovation
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should people be encouraged to take a break from their phones one day a week?', 'You''ll get a whole page in the real IBA exam', 1); -- Technology
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should local languages be taught alongside English in schools to keep them from disappearing?', 'You''ll get a whole page in the real IBA exam', 1); -- Globalization
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Do people generally trust strangers less in big cities than in small towns?', 'You''ll get a whole page in the real IBA exam', 1); -- Human Nature
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should students be encouraged to keep asking "why" even after a teacher gives a clear answer?', 'You''ll get a whole page in the real IBA exam', 1); -- Science
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should public parks be free to enter for everyone, even in expensive neighborhoods?', 'You''ll get a whole page in the real IBA exam', 1); -- Public Policy
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should traditional recipes be preserved exactly, or is it fine for them to change over time?', 'You''ll get a whole page in the real IBA exam', 1); -- Culture
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should people be encouraged to repair broken items instead of simply buying new ones?', 'You''ll get a whole page in the real IBA exam', 1); -- Consumerism
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Does spending time bored actually help people come up with more creative ideas?', 'You''ll get a whole page in the real IBA exam', 1); -- Creativity
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Can a hobby that earns no money still give someone a strong sense of purpose?', 'You''ll get a whole page in the real IBA exam', 1); -- Purpose
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'easy', NULL, 'Should students be allowed to choose their own seating in a classroom?', 'You''ll get a whole page in the real IBA exam', 1); -- Freedom
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should doctors be required to tell patients about mistakes made during treatment, even minor ones?', 'You''ll get a whole page in the real IBA exam', 1); -- Ethics
