INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should citizens be required by law to vote in national elections?', 'You''ll get a whole page in the real IBA exam', 1); -- Democracy
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should comedians be free to joke about any topic, including sensitive ones, without facing consequences?', 'You''ll get a whole page in the real IBA exam', 1); -- Free Speech
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should airlines be taxed extra for the pollution caused by frequent flying?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Environmental Sustainability
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should companies be required to offer mental health days separate from regular sick leave?', 'You''ll get a whole page in the real IBA exam', 1); -- Mental Health
