INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should international sports events be used as a form of diplomacy between rival countries?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- International Relations
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Can someone be considered successful if they achieved their goals but harmed others to get there?', 'You''ll get a whole page in the real IBA exam', 1); -- Success & Failure
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should important life decisions be based more on logic or on gut feeling?', 'You''ll get a whole page in the real IBA exam', 1); -- Decision Making
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Does giving employees more decision-making power make a company run better or slower?', 'You''ll get a whole page in the real IBA exam', 1); -- Power
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Can a country recover from an economic crisis mainly through the hope and confidence of its citizens?', 'You''ll get a whole page in the real IBA exam', 1); -- Hope
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should people be allowed to identify with more than one nationality on official documents?', 'You''ll get a whole page in the real IBA exam', 1); -- Identity
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should religious schools be allowed to receive public government funding?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Religion & Society
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Does publicly shaming corrupt officials actually reduce future corruption?', 'You''ll get a whole page in the real IBA exam', 1); -- Corruption
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'If people consistently make irrational financial decisions, should governments design policy around actual human behavior rather than assuming people act rationally?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Behavioral Psychology
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should a leader ever prioritize the long-term good of an organization over the immediate wellbeing of its members?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Leadership
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should companies be allowed to use customer data to predict and influence purchasing decisions before customers are even aware of wanting something?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Business
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should investors have significant control over a startup''s direction, even when it conflicts with the founder''s original vision?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Entrepreneurship
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Does a two-party political system serve democracy better than a multi-party system, or does it limit real choice?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Democracy
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should breakthrough medical treatments be priced according to what the market will pay, even if it puts them out of reach for many patients?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Innovation
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'As social media algorithms are optimized to maximize engagement, should platforms be required to prioritize user wellbeing over time spent on the app?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Social Media
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Does outsourcing manufacturing to countries with lower labor costs ultimately help or harm workers in those countries?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Globalization
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should museums return artifacts taken during colonial rule to the countries they originally came from?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- History
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Can a work of art be judged separately from the actions or beliefs of the person who created it?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Literature
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should informal settlements in fast-growing cities be formally recognized and upgraded, or gradually relocated to planned housing?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Urbanization
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should companies be held criminally liable, not just fined, when corporate negligence directly causes loss of life?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Law
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should minority languages be actively promoted by the state even when doing so requires resources that could go elsewhere?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Culture
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Does offering endless product choice actually make consumers happier, or does it create anxiety and decision fatigue?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Consumerism
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should wealthy nations bear a greater share of the cost of fighting climate change, since they contributed more to causing it historically?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Environmental Sustainability
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should international organizations like the United Nations have the authority to intervene militarily in a country''s internal conflict to prevent mass atrocities?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Geopolitics
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'As Bangladesh urbanizes rapidly, should the government prioritize expanding Dhaka''s infrastructure or developing secondary cities to ease the pressure?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Bangladesh Development
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Does introducing more oversight and paperwork to prevent corruption end up creating new opportunities for corruption instead?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Corruption
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should countries be allowed to use trade agreements as leverage to pressure other nations on human rights issues?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- International Relations
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should artists be able to claim ownership over a completely new style or technique that others then build upon?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Creativity
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'In high-stakes situations, is it better for one person to have final decision-making authority, or should decisions require group consensus?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Decision Making
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should term limits apply to unelected positions of significant influence, such as central bank governors or supreme court judges?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Power
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Does a country become more resilient to future crises by building redundancy into its systems, even if that means accepting lower everyday efficiency?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Resilience
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'If a fully accurate machine could predict every choice a person will make before they make it, would that undermine free will, or simply reveal how choice actually works?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Philosophy
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'Is it more ethical for a leader to tell a difficult truth that causes short-term panic, or a comforting lie that preserves stability but forecloses informed choice?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Ethics
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'As central banks fight inflation partly by deliberately slowing growth, is it justifiable to accept higher unemployment among the poorest workers to protect everyone else''s purchasing power?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Economics
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'Should democratic governments be allowed to enact policies a majority supports today but that impose serious, irreversible costs on future generations who cannot vote on them?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Public Policy
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'If cooperation, not just competition, is central to human evolutionary success, does this undermine economic systems built primarily on the assumption of self-interest?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Human Nature
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'very_hard', NULL, 'When restorative and retributive justice produce different outcomes for the same crime, which one better serves a society''s long-term interest in preventing future harm?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Justice
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'very_hard', NULL, 'Should scientists be held partly responsible for how their discoveries are later used, even when the harmful application was never intended or foreseeable at the time?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Science
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'As algorithmic curation increasingly replaces human editorial judgment in deciding what billions of people see, has society lost a meaningful check on the shaping of public opinion?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Media
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'If a moral action requires certainty about its consequences, but genuine certainty is rarely possible, should moral responsibility be judged mainly by intention rather than outcome?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Morality
