INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should there be a minimum age requirement to create a social media account?', 'You''ll get a whole page in the real IBA exam', 1); -- Social Media
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should companies be required to provide training when new technology replaces old job tasks?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Future of Work
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Do people change their core personality over time, or mostly stay the same?', 'You''ll get a whole page in the real IBA exam', 1); -- Human Nature
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should school science classes focus more on hands-on experiments than on memorizing facts?', 'You''ll get a whole page in the real IBA exam', 1); -- Science
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should traffic laws be enforced more strictly through cameras rather than police officers?', 'You''ll get a whole page in the real IBA exam', 1); -- Law
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should public schools be allowed to teach comparative religion as a neutral academic subject?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Religion & Society
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should advertisements aimed at young children be restricted on television and online platforms?', 'You''ll get a whole page in the real IBA exam', 1); -- Consumerism
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should government officials be required to publicly declare their income and assets each year?', 'You''ll get a whole page in the real IBA exam', 1); -- Corruption
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should employees have the right to disconnect from work emails after office hours?', 'You''ll get a whole page in the real IBA exam', 1); -- Freedom
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Does believing a situation will improve actually change how hard people work to improve it?', 'You''ll get a whole page in the real IBA exam', 1); -- Hope
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Should retirement mean the end of working, or can people find purpose by continuing to work in some form?', 'You''ll get a whole page in the real IBA exam', 1); -- Purpose
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'medium', NULL, 'Should important government decisions involve public consultation, even if it slows the process down?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Decision Making
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 10, 'medium', NULL, 'Does comparing yourself to others on social media reduce overall life satisfaction?', 'You''ll get a whole page in the real IBA exam', 1); -- Happiness
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'If an employee discovers their company is quietly breaking environmental regulations in a way that harms no one directly yet, should they report it at the risk of losing their job?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Ethical Dilemma
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'If two studies on the same topic reach opposite conclusions, how should a reasonable person decide which one to trust?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Logical Reasoning
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should companies be required to explain how their AI systems reach important decisions, even if doing so reveals valuable trade secrets?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- AI
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should countries that have historically polluted the least be allowed to industrialize using fossil fuels while wealthier nations switch to renewables first?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Climate Change
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Does a strong currency always benefit a country''s economy, or can it hurt exporters and local manufacturing?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Economics
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should university funding be tied to graduates'' future employment and salary outcomes?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Education
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should a leader who successfully turns around a failing organization be forgiven for unethical methods used along the way?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Leadership
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should shareholders be allowed to vote out a CEO who is meeting profit targets but damaging the company''s long-term reputation?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Business
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should governments fund basic scientific research with no clear commercial application, purely for the sake of expanding knowledge?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Innovation
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should coalition governments, formed after no single party wins a majority, be seen as a sign of healthy democracy or political instability?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Politics
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should a private company be allowed to fire an employee for expressing a personal political opinion outside of work?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Free Speech
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Does the spread of a few dominant global languages threaten the survival of thousands of smaller languages worldwide?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Globalization
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should the achievements of flawed historical leaders be separated from their harmful actions when teaching history to students?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- History
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should governments regulate the working hours of gig economy workers, even though these workers are technically self-employed?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Public Policy
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Does mass tourism preserve local cultures by creating an economic incentive to maintain them, or erode them by turning traditions into performances for outsiders?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Culture
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should employers be legally required to accommodate mental health conditions the same way they accommodate physical disabilities?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Mental Health
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should farmers be compensated by the government for switching from profitable but environmentally harmful crops to more sustainable ones?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Environmental Sustainability
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should a country''s history of colonization affect how much responsibility it bears for conflicts in its former colonies today?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Geopolitics
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should Bangladesh prioritize attracting foreign manufacturing investment or building stronger domestic industries that keep more profit within the country?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Bangladesh Development
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'If a self-driving car causes an accident due to a software error, should responsibility fall on the manufacturer, the software engineer, or the owner?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Responsibility
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Should public broadcasters funded by government money be allowed to criticize the very government that funds them?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Media
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should health insurance companies be allowed to use data from fitness tracking apps to set individual premiums?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Digital Privacy
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Does a society that celebrates only dramatic success stories discourage people from valuing slow, steady, less visible achievements?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Success & Failure
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'hard', NULL, 'Should international organizations funded mainly by wealthy nations be trusted to make impartial decisions that sometimes go against those same nations'' interests?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Power
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 12, 'hard', NULL, 'Does the pressure to fund expensive election campaigns make politicians more vulnerable to corruption once in office?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Corruption
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'If future space resources make some nations vastly wealthier than others simply due to a technological head start, does this justify treating space as a shared global commons rather than territory for whoever arrives first?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Space Exploration
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'Given that consumer choice is often shaped more by marketing psychology than by genuine need, can a market economy still be considered to reflect free and rational individual preference?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Consumerism
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'If a well-informed minority consistently makes better long-term decisions than an under-informed majority, does this weaken the moral case for one-person-one-vote democracy?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Democracy
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 13, 'very_hard', NULL, 'As people increasingly form communities online that cross national borders, does traditional national identity remain a meaningful basis for organizing political life?', 'You''ll get a bit more than one page in the real IBA exam', 2); -- Identity
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'Should a nation''s past historical wrongs continue to shape its present-day obligations to other nations indefinitely, or does responsibility diminish with time and changed circumstances?', 'You''ll get one and a half pages in the real IBA exam', 2); -- International Relations
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'If artificial intelligence eventually exceeds human capability across nearly all domains, what, if anything, would remain the basis for uniquely human dignity and worth?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Innovation
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'Should legal systems built on the idea of individual responsibility be reconsidered as neuroscience reveals how much human behavior is shaped by factors outside a person''s control?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Law
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('basic_paragraph', 15, 'very_hard', NULL, 'If an action produces the best outcome for the greatest number but requires violating an individual''s fundamental rights, should the outcome or the principle take precedence?', 'You''ll get one and a half pages in the real IBA exam', 2); -- Ethics
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Oscar Wilde wrote, "Be yourself; everyone else is already taken." Explain what this quote means, and discuss whether it is always good advice.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Oscar Wilde wrote, "We are all in the gutter, but some of us are looking at the stars." Analyze what this suggests about hardship and hope, and evaluate whether outlook alone can change one''s circumstances.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'Oscar Wilde wrote, "The truth is rarely pure and never simple." Analyze what this suggests about how people communicate difficult truths, and evaluate whether complete honesty is ever truly achievable.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Oscar Wilde wrote, "To live is the rarest thing in the world. Most people exist, that is all." Analyze the distinction Wilde draws here, and discuss what it might mean to truly "live."', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'medium', NULL, 'Oscar Wilde wrote, "Experience is simply the name we give our mistakes." Analyze what this suggests about the value of failure, and share your own view.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Nelson Mandela said, "It always seems impossible until it''s done." Explain what this quote means, and give an example where it applies.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Nelson Mandela said, "Education is the most powerful weapon which you can use to change the world." Analyze why Mandela may have believed this, and discuss whether education alone is enough to drive real change.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Nelson Mandela said, "I never lose. I either win or learn." Explain what this mindset means, and discuss why it might be useful.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Nelson Mandela said, "A good head and a good heart are always a formidable combination." Analyze what balance Mandela is describing, and discuss why one alone may not be enough.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'Nelson Mandela said, "Courage is not the absence of fear, but the triumph over it." Analyze this definition of courage, and evaluate whether someone who feels no fear at all can truly be called brave.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'medium', NULL, 'Albert Einstein said, "Imagination is more important than knowledge." Analyze why Einstein might have believed this, and discuss whether you agree.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Albert Einstein said, "A person who never made a mistake never tried anything new." Explain what this quote means, using an example.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Albert Einstein said, "Life is like riding a bicycle. To keep your balance you must keep moving." Analyze what this metaphor suggests about stability and progress in life.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Albert Einstein said, "In the middle of difficulty lies opportunity." Explain what this quote means, and give an example.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'Albert Einstein said, "Try not to become a person of success, but rather a person of value." Analyze the distinction Einstein draws here, and evaluate whether success and value can ever be separated in practice.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Steve Jobs said, "Your time is limited, so don''t waste it living someone else''s life." Analyze what this suggests about conformity and individual choice, and discuss whether this advice is realistic for everyone.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'medium', NULL, 'Steve Jobs said, "Innovation distinguishes between a leader and a follower." Analyze what this suggests about the role of innovation in leadership.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'Steve Jobs said, "People who think they can change the world are usually the ones who do." Analyze what this suggests about belief and achievement, and evaluate whether self-belief alone can explain success.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Steve Jobs said, "Stay hungry, stay foolish." Explain what this quote means, and discuss why it might be useful advice.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Steve Jobs said, "Sometimes life is going to hit you in the head with a brick." Analyze what this suggests about setbacks, and discuss how people can respond to them productively.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Confucius said, "It matters not how slowly you go, so long as you do not stop." Explain what this quote means, using an example.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Confucius said, "Our greatest glory lies not in never falling, but rising each time we fall." Analyze what this suggests about failure and character, and discuss whether this applies equally to every kind of failure.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Confucius said, "The man who moves a mountain begins by carrying away small stones." Analyze what this suggests about tackling large goals, and discuss whether this approach always works.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'hard', NULL, 'Confucius said, "Real knowledge is to know the extent of one''s ignorance." Analyze what this suggests about intellectual humility, and evaluate whether admitting ignorance is a strength or a weakness.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Confucius said, "By three methods we may learn wisdom: reflection, imitation, and experience." Analyze the three paths Confucius describes, and discuss which one you find most valuable.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Nietzsche wrote, "That which does not kill us makes us stronger." Explain what this quote means, and discuss whether hardship always strengthens a person.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'Nietzsche wrote, "He who fights monsters should ensure he himself does not become a monster." Analyze what this warns about opposing something harmful, and evaluate whether this danger is unavoidable.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'medium', NULL, 'Nietzsche wrote, "Without music, life would be a mistake." Analyze what this suggests about the role of art in human life, and share your own view.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'very_hard', NULL, 'Nietzsche wrote, "There are no facts, only interpretations." Analyze the philosophical claim this quote makes about objectivity and truth, and evaluate whether this idea can be applied consistently without undermining itself.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'very_hard', NULL, 'Marcus Aurelius wrote, "You have power over your mind, not outside events. Realize this, and find strength." Analyze the Stoic principle behind this claim, and evaluate its limits when events genuinely threaten someone''s wellbeing.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Marcus Aurelius wrote, "The best revenge is to be unlike him who performed the injury." Analyze what this suggests about responding to wrongdoing, and discuss whether this is always realistic.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'Marcus Aurelius wrote, "Waste no more time arguing about what a good man should be. Be one." Analyze what this suggests about the relationship between debate and action, and evaluate whether discussing ethics is ever truly a waste of time.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Marcus Aurelius wrote, "Very little is needed to make a happy life." Explain what this quote means, and discuss whether you agree.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Rumi wrote, "Today I am wise, so I am changing myself." Explain what this quote means, and discuss why this shift in focus matters.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Rumi wrote, "Raise your words, not your voice. It is rain that grows flowers, not thunder." Analyze what this suggests about persuasion and influence, and discuss whether gentleness is always more effective than force.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'medium', NULL, 'Rumi wrote, "The quieter you become, the more you are able to hear." Analyze what this suggests about listening and self-reflection.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'Rumi wrote, "Don''t grieve. Anything you lose comes round in another form." Analyze what this suggests about loss and change, and evaluate whether this idea offers genuine comfort or avoids the reality of loss.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Maya Angelou said, "There is no greater agony than bearing an untold story inside you." Analyze what this suggests about self-expression, and discuss why some stories remain untold.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Maya Angelou said, "You cannot control events, but you can choose your response to them." Analyze what this suggests about control and resilience, and discuss whether this is always possible in practice.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Maya Angelou said, "If you don''t like something, change it; if you can''t, change your attitude." Explain what this quote means, using an example.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Maya Angelou said, "Nothing will work unless you do." Explain what this quote means, and discuss why it might be true.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Aristotle wrote, "We are what we repeatedly do; excellence is a habit, not an act." Analyze what this suggests about how character is formed, and discuss whether a single great act can outweigh a pattern of habits.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Aristotle wrote, "Knowing yourself is the beginning of all wisdom." Explain what this quote means, and discuss why self-knowledge might be difficult to achieve.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'Aristotle wrote, "The mark of an educated mind is entertaining a thought without accepting it." Analyze what this suggests about open-mindedness, and evaluate whether there are ideas that should not be entertained at all.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Aristotle wrote, "Educating the mind without educating the heart is no education at all." Analyze what this suggests about the purpose of education, and discuss whether modern schooling achieves this balance.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'medium', NULL, 'Aristotle wrote, "The whole is greater than the sum of its parts." Analyze what this suggests about teamwork and systems, using an example.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Socrates said, "The only true wisdom is in knowing you know nothing." Explain what this quote means, and discuss why this idea can be difficult to accept.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'hard', NULL, 'Socrates said, "An unexamined life is not worth living." Analyze what this suggests about self-reflection, and evaluate whether this claim is too extreme.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Socrates said, "I cannot teach anybody anything. I can only make them think." Analyze what this suggests about the true purpose of teaching, and discuss whether this view still applies to modern education.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'very_hard', NULL, 'Socrates is said to have taught, "There is only one good, knowledge, and one evil, ignorance." Analyze the philosophical claim behind this statement, and evaluate whether ignorance can fully explain the existence of wrongdoing.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Socrates is said to have taught, "Wonder is the beginning of wisdom." Explain what this quote means, and discuss why curiosity matters.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Winston Churchill said, "Success is never final; failure is rarely fatal; it''s courage that counts." Analyze what this suggests about resilience over time, and discuss whether courage alone is enough to sustain long-term success.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Winston Churchill said, "We make a living by what we get, but life by what we give." Analyze the distinction Churchill draws here, and discuss whether both are equally necessary.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Winston Churchill said, "Attitude is a little thing that makes a big difference." Explain what this quote means, using an example.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Winston Churchill said, "Difficulties mastered are opportunities won." Explain what this quote means, and discuss why this reframing might be useful.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'Winston Churchill said, "To improve is to change; to be perfect is to change often." Analyze what this suggests about growth and consistency, and evaluate whether constant change can ever undermine genuine improvement.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Abraham Lincoln said, "I am a slow walker, but I never walk back." Explain what this quote means, and discuss why it might be true.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Abraham Lincoln said, "Whatever you are, be a good one." Explain what this quote means, using an example.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'medium', NULL, 'Abraham Lincoln said, "Character is like a tree and reputation like its shadow." Analyze the distinction Lincoln draws here, and discuss which one people tend to focus on more.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'Abraham Lincoln said, "If you want to test a man''s character, give him power." Analyze what this suggests about power and integrity, and evaluate whether this test is truly reliable.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Abraham Lincoln said, "You cannot escape the responsibility of tomorrow by evading it today." Analyze what this suggests about procrastination, and discuss why people avoid responsibility despite knowing this.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Martin Luther King Jr. said, "Darkness cannot drive out darkness; only light can do that." Analyze what this suggests about responding to hatred, and discuss whether this principle is always practical.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'Martin Luther King Jr. said, "The true measure of a man is where he stands in times of challenge." Analyze what this suggests about character under pressure, and discuss whether comfort can also reveal character.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'hard', NULL, 'Martin Luther King Jr. said, "Injustice anywhere is a threat to justice everywhere." Analyze what this suggests about the interconnectedness of injustice, and evaluate whether individuals can realistically act on this idea.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Martin Luther King Jr. said, "Faith is taking the first step even when you don''t see the whole staircase." Analyze what this suggests about uncertainty and action, using an example.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'Martin Luther King Jr. said, "Our lives begin to end the day we become silent about things that matter." Analyze what this suggests about speaking up, and evaluate whether silence is ever the wiser choice.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Rabindranath Tagore wrote, "Where the mind is without fear and the head is held high." Analyze the ideal Tagore describes in this line, and discuss what conditions make it difficult to achieve.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Rabindranath Tagore wrote, "You can''t cross the sea merely by standing and staring at the water." Explain what this quote means, using an example.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'Rabindranath Tagore wrote, "Faith is the bird that feels the light when the dawn is still dark." Analyze what this metaphor suggests about hope in uncertain times, and evaluate whether faith without evidence can be a rational response.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'very_hard', NULL, 'Rabindranath Tagore wrote, "We read the world wrong and say that it deceives us." Analyze the philosophical claim behind this line, and evaluate whether misperception or genuine deception better explains human disappointment.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Rabindranath Tagore wrote, "Facts are many, but the truth is one." Explain what this quote means, using an example.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'In Pride and Prejudice, Jane Austen opens with the line, "A man of good fortune must be in want of a wife." Explain the irony in this statement, using an example from the story or from life.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'In Emma, a character says, "There is nothing I would not do for those who are really my friends." Analyze what this suggests about the nature of true friendship, and discuss whether such loyalty is always wise.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Jane Austen wrote, "It isn''t what we say or think that defines us, but what we do." Analyze what this suggests about the relationship between intention and action, and discuss whether this is entirely fair.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'In Pride and Prejudice, a character exclaims, "I declare after all there is no enjoyment like reading!" Explain what this line suggests about the character, and discuss whether the sentiment is genuine.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'In Pride and Prejudice, Mary Bennet observes, "Vanity and pride are different things, though the words are often used synonymously." Analyze the distinction being drawn, and evaluate whether it still holds true today.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'In his poem "Bidrohi" ("The Rebel"), Kazi Nazrul Islam writes, "I am the rebel eternal, I raise my head beyond this world, alone and high." Analyze what this line suggests about defiance and identity, and discuss what it might mean to be a "rebel" in a constructive sense.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'medium', NULL, 'In his poem "Bidrohi" ("The Rebel"), Kazi Nazrul Islam repeats the refrain, "Say, hero, say: my head is held high!" Analyze the tone and purpose of this repeated line, using an example of when such defiance might be needed.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'In George Orwell''s novel "1984," citizens are reminded, "Big Brother is watching you." Explain what this phrase suggests about surveillance and control, using a modern-day example.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'In George Orwell''s "Animal Farm," the pigs declare, "All animals are equal, but some animals are more equal than others." Analyze what this line satirizes, and discuss where you see similar contradictions today.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'In "1984," George Orwell writes the Party slogan, "War is peace. Freedom is slavery. Ignorance is strength." Analyze how this slogan works as a tool of control, and evaluate whether similar contradictions appear in real political language today.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'very_hard', NULL, 'George Orwell wrote, "Political language is designed to make lies sound truthful and murder respectable." Analyze the mechanism Orwell is describing, and evaluate whether ordinary citizens can realistically defend themselves against it.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'In "1984," George Orwell writes, "Whoever is winning at the moment will always seem to be invincible." Analyze what this suggests about how power appears versus how stable it actually is.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'George Orwell wrote, "Liberty means the right to tell people what they do not want to hear." Analyze what this suggests about the discomfort inherent in real free speech, and evaluate whether all uncomfortable speech deserves equal protection.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'very_hard', NULL, 'Carl Jung wrote, "What you don''t make conscious will direct your life, and you''ll call it fate." Analyze the psychological claim behind this statement, and evaluate whether people can ever fully know their own unconscious motives.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'Carl Jung wrote, "Everything that irritates us about others can lead us to an understanding of ourselves." Analyze the psychological idea behind this claim, and evaluate whether this is true of all irritation or only some.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'medium', NULL, 'Carl Jung wrote, "Who looks outside, dreams; who looks inside, awakes." Analyze what this suggests about self-reflection versus external distraction.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Carl Jung wrote, "The privilege of a lifetime is to become who you truly are." Analyze what this suggests about identity and authenticity, and discuss what might get in the way of this process.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'hard', NULL, 'Carl Jung wrote, "There is no coming to consciousness without pain." Analyze what this suggests about the process of personal growth, and evaluate whether growth is truly impossible without suffering.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Carl Jung wrote, "Your visions will become clear only when you can look into your own heart." Analyze what this suggests about self-awareness and clarity, using an example.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Viktor Frankl wrote, "When we can no longer change a situation, we are challenged to change ourselves." Analyze what this suggests about control and adaptation, using an example.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'Viktor Frankl wrote, "The last human freedom is to choose one''s own attitude in any circumstance." Analyze this idea in the context of extreme adversity, and evaluate whether this freedom is truly available to everyone.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'hard', NULL, 'Viktor Frankl wrote, "Suffering ceases to be suffering the moment it finds a meaning." Analyze what this suggests about the relationship between meaning and pain, and evaluate whether all suffering can be given meaning.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'very_hard', NULL, 'Viktor Frankl wrote, "What is to give light must endure burning." Analyze the metaphor behind this statement, and evaluate whether meaningful contribution truly requires personal sacrifice.', 'You''ll get about half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 6, 'medium', NULL, 'Viktor Frankl wrote, "Life is never made unbearable by circumstances, but only by lack of meaning and purpose." Analyze what this suggests about resilience, and discuss whether this claim goes too far.', 'You''ll get a bit more than half a page in the real IBA exam', 1);
INSERT INTO questions (category, marks, difficulty, source, prompt, space_hint, max_images) VALUES ('quote_analysis', 5, 'easy', NULL, 'Viktor Frankl wrote, "An abnormal reaction to an abnormal situation is normal behavior." Explain what this quote means, using an example.', 'You''ll get about half a page in the real IBA exam', 1);
